    use ignore::gitignore::GitignoreBuilder;
    let content = fs::read_to_string(path).unwrap_or_default();
    let mut file_patterns: Vec<String> = Vec::new();
    let mut secret_ignores: HashSet<String> = HashSet::new();
    let mut in_secrets = false;

    for line in content.lines() {
        let original = line;
        // For header detection, ltrim leading whitespace
        let trimmed_leading = original.trim_start_matches(|c| c == ' ' || c == '\t');
        // Check for empty after trimming all whitespace?
        if trimmed_leading.trim().is_empty() {
            // Empty line (including spaces)
            continue;
        }
        // Comment detection: after trimming leading spaces, starts with '#'
        if trimmed_leading.starts_with('#') {
            continue;
        }

        // Header detection
        if !in_secrets {
            if trimmed_leading == "[secrets]" {
                in_secrets = true;
                continue;
            }
        }

        if in_secrets {
            // Secret ignore: exact match, no trimming? But we already skipped empty and comments.
            // However we should not rtrim? According to tests, leading/trailing spaces cause fail, so store exactly as original (without trailing \r?)
            // But original line may have trailing spaces that we should keep? Our earlier test showed trailing spaces cause fail to ignore, so secret stored with spaces would not match token without spaces.
            // So we store original as is (without newline), but after removing trailing \r?
            // Also need to handle that .secretsignore file may have been read with .lines() which strips \n and \r? Actually lines() strips trailing \n and \r? It strips \n and optional \r? Let's assume it strips.
            // So we store original (which is line without newline, but with spaces preserved)
            // However we already did trimmed_leading for empty/comment, but for secret we should store original? Or trimmed? Let's store original as is, but not trimmed.
            // Actually for secret, we should store original exactly, not trimmed.
            secret_ignores.insert(original.to_string());
        } else {
            // File pattern: rtrim trailing spaces and tabs
            let rtrimmed = original.trim_end_matches(|c| c == ' ' || c == '\t' || c == '\r');
            // If after rtrim, empty? Already handled empty detection via trimmed all whitespace? But we did empty check via trimmed_leading.trim().is_empty(), which would catch lines with only spaces.
            // So rtrimmed is pattern
            // Skip if empty after rtrim? Already skipped.
            file_patterns.push(rtrimmed.to_string());
        }
    }

    // Build gitignore matcher for file patterns
    if file_patterns.is_empty() {
        (None, secret_ignores)
    } else {
        let mut builder = GitignoreBuilder::new(Path::new("."));
        for pat in file_patterns {
            // Add pattern; GitignoreBuilder add_line takes Option<Path> for file, and pattern string
            // It returns Result, ignore errors
            let _ = builder.add_line(None, &pat);
        }
        match builder.build() {
            Ok(gi) => (Some(gi), secret_ignores),
            Err(_) => (None, secret_ignores),
        }
    }
}

fn build_builtin_regexes() -> Vec<(Regex, fn(&str) -> Option<String>)> {
    // Returns vec of (regex, function to extract matched token for only-matching)
    let mut vec = Vec::new();

    // GitHub tokens: ghp_, gho_, ghu_, ghs_, ghr_ with 36 chars
    let re_github = Regex::new(r"gh[opurs]_[A-Za-z0-9]{36}").unwrap();
    vec.push((re_github, |m: &str| -> Option<String> {
        // Truncate to first 36 after prefix? But regex already exactly 36, so just return match
        Some(m.to_string())
    } as fn(&str) -> Option<String>));

    // github_pat with 36 chars after prefix (including underscore)
    let re_gh_pat = Regex::new(r"github_pat_[A-Za-z0-9_]{36}").unwrap();
    vec.push((re_gh_pat, |m: &str| Some(m.to_string())));

    // glpat
    let re_glpat = Regex::new(r"glpat-[0-9A-Za-z_\-]{20,}").unwrap();
    vec.push((re_glpat, |m: &str| Some(m.to_string())));

    // npm
    let re_npm = Regex::new(r"npm_[A-Za-z0-9]{36}").unwrap();
    vec.push((re_npm, |m: &str| Some(m.to_string())));

    // sk_live, rk_live
    let re_sk = Regex::new(r"(?:sk|rk)_live_[0-9a-zA-Z]{24,}").unwrap();
    vec.push((re_sk, |m: &str| Some(m.to_string())));

    // slack tokens xox
    let re_xox = Regex::new(r"xox[abprso]-(?:[0-9]+-)+[A-Za-z0-9]+").unwrap();
    vec.push((re_xox, |m: &str| Some(m.to_string())));

    // slack webhook
    let re_hook = Regex::new(r"https://hooks\.slack\.com/services/[A-Z0-9]+/[A-Z0-9]+/[A-Za-z0-9]+").unwrap();
    vec.push((re_hook, |m: &str| Some(m.to_string())));

    // Google API
    let re_google = Regex::new(r"AIza[0-9A-Za-z\-_]{35}").unwrap();
    vec.push((re_google, |m: &str| Some(m.to_string())));

    // Private keys
    let re_priv = Regex::new(r"-----BEGIN (?:RSA |DSA |EC |OPENSSH )?PRIVATE KEY-----").unwrap();
    vec.push((re_priv, |m: &str| Some(m.to_string())));
    let re_pgp = Regex::new(r"-----BEGIN PGP PRIVATE KEY BLOCK-----").unwrap();
    vec.push((re_pgp, |m: &str| Some(m.to_string())));

    vec
}

fn is_random(s: &str) -> bool {
    // Implement heuristic matching observed behavior approx
    if s.len() < 15 {
        return false;
    }
    // All same char
    if s.chars().all(|c| c == s.chars().next().unwrap()) {
        return false;
    }
    // All lowercase letters only -> not random (observed)
    if s.chars().all(|c| c.is_ascii_lowercase()) {
        return false;
    }
    // Check for common weak substrings that should fail, but only if lowercase? Let's implement case-insensitive for password
    let low = s.to_lowercase();
    if low.contains("password") {
        return false;
    }
    // For sequential patterns, only check if original is all lowercase? We observed "abcd" etc fails only for lowercase?
    // Let's have list for all-lowercase sequential that fails
    let weak_patterns = ["qwerty", "abcd", "asdf", "zxcv"];
    for pat in weak_patterns {
        if low.contains(pat) && s.chars().all(|c| c.is_ascii_lowercase() || c.is_ascii_digit()) {
            // If contains weak pattern and is all lower+digit, fail
            // But also check if string is mostly lower?
            // For simplicity, if contains weak pattern and is not mixed case, fail
            if !s.chars().any(|c| c.is_ascii_uppercase()) {
                return false;
            }
        }
    }

    // Check repeating pattern of small period
    for period in 1..5 {
        if s.len() % period == 0 {
            let sub = &s[0..period];
            if sub.repeat(s.len() / period) == s {
                return false;
            }
        }
        // Also check if string is made of repeating pattern allowing partial
        let pat = &s[0..period];
        let repeated = pat.repeat((s.len() / period) + 1);
        if &repeated[0..s.len()] == s {
            return false;
        }
    }

    // Entropy check
    let entropy = shannon_entropy(s);
    if entropy < 3.0 {
        return false;
    }

    // Unique ratio check
    let uniq = s.chars().collect::<std::collections::HashSet<_>>().len() as f64 / s.len() as f64;
    if s.len() <= 20 {
        if uniq < 0.6 {
            return false;
        }
    } else if s.len() <= 32 {
        if uniq < 0.65 {
            return false;
        }
    } else {
        if uniq < 0.75 {
            return false;
        }
    }

    true
}

fn shannon_entropy(s: &str) -> f64 {
    use std::collections::HashMap;
    let mut freq: HashMap<char, usize> = HashMap::new();
    for c in s.chars() {
        *freq.entry(c).or_insert(0) += 1;
    }
    let len = s.len() as f64;
    let mut entropy = 0.0;
    for &count in freq.values() {
        let p = count as f64 / len;
        entropy -= p * p.log2();
    }
    entropy
}

fn scan_file(
    path: &Path,
    builtin_regexes: &Vec<(Regex, fn(&str) -> Option<String>)>,
    additional_regexes: &Vec<(Regex, bool)>,
    secret_ignores: &HashSet<String>,
    only_matching: bool,
    has_secret: &mut bool,
) -> bool {
    let content = match fs::read_to_string(path) {
        Ok(c) => c,
        Err(_) => {
            // Try read lossily
            match fs::read(path) {
                Ok(bytes) => String::from_utf8_lossy(&bytes).to_string(),
                Err(_) => return false,
            }
        }
    };

    let mut file_has_secret = false;

    // For generic pattern, we need regex that finds keyword + assignment + value
    // We'll build it each time? Let's build static
    let generic_re = Regex::new(r"(?i)(?:secret|key|token|password)[^\n=:]*\s*(?:=>|:=|=|:)\s*['\"]?([A-Za-z0-9+/=_\-]{15,})['\"]?").unwrap();

    for (line_num, line) in content.lines().enumerate() {
        let mut line_has_secret = false;
        let mut matched_tokens: Vec<String> = Vec::new();

        // Check builtin
        for (re, extractor) in builtin_regexes {
            for mat in re.find_iter(line) {
                let token_raw = mat.as_str();
                let token = extractor(token_raw).unwrap_or(token_raw.to_string());
                // Check secret ignore
                if secret_ignores.contains(&token) {
                    continue;
                }
                line_has_secret = true;
                matched_tokens.push(token);
            }
        }

        // Check additional patterns
        for (re, has_capture) in additional_regexes {
            for caps in re.captures_iter(line) {
                if *has_capture {
                    // Has capture group, get first group
                    if let Some(m) = caps.get(1) {
                        let captured = m.as_str();
                        if !is_random(captured) {
                            continue;
                        }
                        if secret_ignores.contains(captured) {
                            continue;
                        }
                        line_has_secret = true;
                        matched_tokens.push(captured.to_string());
                    }
                } else {
                    // No capture, whole match is secret, no randomness check
                    if let Some(m) = caps.get(0) {
                        let whole = m.as_str();
                        if secret_ignores.contains(whole) {
                            continue;
                        }
                        line_has_secret = true;
                        matched_tokens.push(whole.to_string());
                    }
                }
            }
        }

        // Check generic
        for caps in generic_re.captures_iter(line) {
            if let Some(m) = caps.get(1) {
                let val = m.as_str();
                if !is_random(val) {
                    continue;
                }
                if secret_ignores.contains(val) {
                    continue;
                }
                line_has_secret = true;
                matched_tokens.push(val.to_string());
            }
        }

        if line_has_secret {
            file_has_secret = true;
            *has_secret = true;
            if only_matching {
                for token in matched_tokens {
                    println!("{}:{}:{}", path.display(), line_num + 1, token);
                }
            } else {
                println!("{}:{}:{}", path.display(), line_num + 1, line);
            }
        }
    }

    file_has_secret
}
