            // Actually we saw lowercase qwerty fails, uppercase passes
            return false;
        }
    }
    for period in 1..5 {
        if s.len() % period == 0 {
            let sub = &s[0..period];
            if sub.repeat(s.len() / period) == s {
                return false;
            }
        }
        let pat = &s[0..period];
        let repeated = pat.repeat((s.len() / period) + 1);
        if &repeated[0..s.len()] == s {
            return false;
        }
    }
    let entropy = shannon_entropy(s);
    if entropy < 3.0 {
        return false;
    }
    let uniq = s.chars().collect::<HashSet<_>>().len() as f64 / s.len() as f64;
    if s.len() <= 20 {
        if uniq < 0.6 {
            return false;
        }
    } else if s.len() <= 32 {
        if uniq < 0.65 {
            return false;
        }
    } else {
        if uniq < 0.75 {
            return false;
        }
    }
    true
