        if src_path.is_file() {
            // Skip .secretsignore and .gitignore themselves
            if let Some(fname) = src_path.file_name() {
                if fname == ".secretsignore" || fname == ".gitignore" {
                    // Unless explicitly passed and not strict? For explicit file, we already handled strict.
                    // But original seems to ignore .secretsignore even when explicitly passed?
                    // Let's check: if .secretsignore contains secret and we explicitly pass it, does it report?
