use clap::{Arg, ArgAction, Command};
use regex::Regex;
use std::collections::HashSet;
use std::fs;
use std::path::{Path, PathBuf};
use std::process;

fn main() {
    let cmd = Command::new("ripsecrets")
        .version("0.1.11")
        .about("ripsecrets searches files and directories recursively for secret API keys.\nIt's primarily designed to be used as a pre-commit to prevent committing\nsecrets into version control.")
        .arg(
            Arg::new("install-pre-commit")
                .long("install-pre-commit")
                .help("Install `ripsecrets` as a pre-commit hook automatically in git directory provided")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("strict-ignore")
                .long("strict-ignore")
                .help("If you pass a path as an argument that's ignored by .secretsignore it will be scanned by default. --strict-ignore will override this behavior and not search the paths passed as arguments that are excluded by the .secretsignore file. This is useful when invoking secrets as a pre-commit")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("only-matching")
                .long("only-matching")
                .help("Print only the matched (non-empty) parts of a matching line, with each such part on a separate output line")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("additional-pattern")
                .long("additional-pattern")
                .value_name("ADDITIONAL_PATTERNS")
                .help("Additional regex patterns used to find secrets. If there is a matching group in the regex the matched group will be tested for randomness before being reported as a secret")
                .action(ArgAction::Append),
        )
        .arg(
            Arg::new("source")
                .value_name("Source files")
                .help("Source files. Can be files or directories. Defaults to '.'")
                .action(ArgAction::Append),
        );

    let matches = cmd.clone().get_matches();

    let install = matches.get_flag("install-pre-commit");
    let strict_ignore = matches.get_flag("strict-ignore");
    let only_matching = matches.get_flag("only-matching");
    let additional_patterns: Vec<String> = matches
        .get_many::<String>("additional-pattern")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();
    let sources: Vec<String> = matches
        .get_many::<String>("source")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();

    if install {
        if strict_ignore {
            eprintln!("Error: --strict-ignore is not a valid option when installing pre-commits. Use --install-pre-commit alone");
            process::exit(2);
        }
        if only_matching {
            eprintln!("Error: --only-matching is not a valid option when installing pre-commits. Use --install-pre-commit alone");
            process::exit(2);
        }
        if !additional_patterns.is_empty() {
            eprintln!("Error: --additional-pattern is not a valid option when installing pre-commits. Use --install-pre-commit alone");
            process::exit(2);
        }

        let target_dir = if sources.is_empty() {
            PathBuf::from(".")
        } else {
            PathBuf::from(&sources[0])
        };

        let git_path = target_dir.join(".git");
        if !git_path.is_dir() {
            eprintln!("Error: .git directory not found");
            process::exit(2);
        }

        let hooks_dir = git_path.join("hooks");
        let pre_commit_path = hooks_dir.join("pre-commit");
        let hook_content = "ripsecrets --strict-ignore `git diff --cached --name-only --diff-filter=ACM`\n";
        if pre_commit_path.exists() {
            if let Ok(existing) = fs::read_to_string(&pre_commit_path) {
                if existing.contains("ripsecrets --strict-ignore `git diff --cached --name-only --diff-filter=ACM`") {
                    eprintln!("Error: pre-commit hook has already been installed");
                    process::exit(2);
                }
            }
            let existing = fs::read_to_string(&pre_commit_path).unwrap_or_default();
            let new_content = if existing.is_empty() || existing.ends_with('\n') {
                format!("{}{}", existing, hook_content)
            } else {
                format!("{}\n{}", existing, hook_content)
            };
            if let Err(e) = fs::write(&pre_commit_path, new_content) {
                eprintln!("Error: failed to write pre-commit hook: {}", e);
                process::exit(2);
            }
        } else {
            if let Err(e) = fs::write(&pre_commit_path, hook_content) {
                eprintln!("Error: failed to write pre-commit hook: {}", e);
                process::exit(2);
            }
            #[cfg(unix)]
            {
                use std::os::unix::fs::PermissionsExt;
                if let Ok(meta) = fs::metadata(&pre_commit_path) {
                    let mut perm = meta.permissions();
                    perm.set_mode(0o744);
                    let _ = fs::set_permissions(&pre_commit_path, perm);
                }
            }
        }

        process::exit(0);
    }

    let secrets_ignore_path = Path::new(".secretsignore");
    let (file_ignore_matcher, secret_ignores) = if secrets_ignore_path.exists() {
        parse_secretsignore(secrets_ignore_path)
    } else {
        (None, HashSet::new())
    };

    let mut additional_regexes: Vec<(Regex, bool)> = Vec::new();
    for pat in &additional_patterns {
        match Regex::new(pat) {
            Ok(re) => {
                let has_capture = re.captures_len() > 1;
                additional_regexes.push((re, has_capture));
            }
            Err(e) => {
                eprintln!("Error: invalid regex '{}': {}", pat, e);
                process::exit(2);
            }
        }
    }

    let src_paths: Vec<PathBuf> = if sources.is_empty() {
        vec![PathBuf::from(".")]
    } else {
        sources.iter().map(PathBuf::from).collect()
    };

    let mut has_secret = false;

    let is_ignored_by_file_patterns = |path: &Path, matcher: &Option<ignore::gitignore::Gitignore>| -> bool {
        if let Some(ref m) = matcher {
            let is_dir = path.is_dir();
            let matched = m.matched(path, is_dir);
            if matched.is_ignore() {
                return true;
            }
        }
        false
    };

    let builtin_regexes = build_builtin_regexes();

    for src in &src_paths {
        let src_path = src.as_path();
        if !src_path.exists() {
            println!("{}: No such file or directory (os error 2)", src_path.display());
            continue;
        }

        let src_ignored = is_ignored_by_file_patterns(src_path, &file_ignore_matcher);
        if src_ignored && strict_ignore {
            continue;
        }

        if src_path.is_file() {
            if let Some(fname) = src_path.file_name() {
                if fname == ".secretsignore" || fname == ".gitignore" {
                    continue;
                }
            }
            scan_file(src_path, &builtin_regexes, &additional_regexes, &secret_ignores, only_matching, &mut has_secret);
        } else if src_path.is_dir() {
            let mut builder = ignore::WalkBuilder::new(src_path);
            builder.hidden(false);
            builder.git_ignore(true);
            builder.ignore(true);
            builder.git_global(false);
            builder.git_exclude(false);
            builder.filter_entry(|entry| {
                let path = entry.path();
                if path.file_name().map(|n| n == ".git").unwrap_or(false) {
                    return false;
                }
                if let Some(fname) = path.file_name() {
                    if fname == ".secretsignore" || fname == ".gitignore" {
                        return false;
                    }
                }
                true
            });

            let walker = builder.build();

            for entry in walker {
                match entry {
                    Ok(e) => {
                        let path = e.path();
                        if path.is_file() {
                            let mut should_skip = false;
                            if !src_ignored || strict_ignore {
                                if src_ignored && !strict_ignore {
                                    should_skip = false;
                                } else {
                                    if is_ignored_by_file_patterns(path, &file_ignore_matcher) {
                                        should_skip = true;
                                    }
                                }
                            }

                            if should_skip {
                                continue;
                            }

                            if let Some(fname) = path.file_name() {
                                if fname == ".secretsignore" || fname == ".gitignore" {
                                    continue;
                                }
                            }

                            scan_file(path, &builtin_regexes, &additional_regexes, &secret_ignores, only_matching, &mut has_secret);
                        }
                    }
                    Err(_) => continue,
                }
            }
        }
    }

    if has_secret {
        process::exit(1);
    } else {
        process::exit(0);
    }
}

fn parse_secretsignore(path: &Path) -> (Option<ignore::gitignore::Gitignore>, HashSet<String>) {
    use ignore::gitignore::GitignoreBuilder;
    let content = fs::read_to_string(path).unwrap_or_default();
    let mut file_patterns: Vec<String> = Vec::new();
    let mut secret_ignores: HashSet<String> = HashSet::new();
    let mut in_secrets = false;

    for line in content.lines() {
        let original = line;
        let trimmed_leading = original.trim_start_matches(|c| c == ' ' || c == '\t');
        if trimmed_leading.trim().is_empty() {
            continue;
        }
        if trimmed_leading.starts_with('#') {
            continue;
        }

        if !in_secrets {
            if trimmed_leading == "[secrets]" {
                in_secrets = true;
                continue;
            }
        }

        if in_secrets {
            secret_ignores.insert(original.to_string());
        } else {
            let rtrimmed = original.trim_end_matches(|c| c == ' ' || c == '\t' || c == '\r');
            if rtrimmed.is_empty() {
                continue;
            }
            file_patterns.push(rtrimmed.to_string());
        }
    }

    if file_patterns.is_empty() {
        (None, secret_ignores)
    } else {
        let mut builder = GitignoreBuilder::new(Path::new("."));
        for pat in file_patterns {
            let _ = builder.add_line(None, &pat);
        }
        match builder.build() {
            Ok(gi) => (Some(gi), secret_ignores),
            Err(_) => (None, secret_ignores),
        }
    }
}

fn build_builtin_regexes() -> Vec<(Regex, fn(&str) -> Option<String>)> {
    let mut vec = Vec::new();

    let re_github = Regex::new(r"gh[opurs]_[A-Za-z0-9]{36}").unwrap();
    vec.push((re_github, |m: &str| -> Option<String> { Some(m.to_string()) } as fn(&str) -> Option<String>));

    let re_gh_pat = Regex::new(r"github_pat_[A-Za-z0-9_]{36}").unwrap();
    vec.push((re_gh_pat, |m: &str| Some(m.to_string())));

    let re_glpat = Regex::new(r"glpat-[0-9A-Za-z_\-]{20,}").unwrap();
    vec.push((re_glpat, |m: &str| Some(m.to_string())));

    let re_npm = Regex::new(r"npm_[A-Za-z0-9]{36}").unwrap();
    vec.push((re_npm, |m: &str| Some(m.to_string())));

    let re_sk = Regex::new(r"(?:sk|rk)_live_[0-9a-zA-Z]{24,}").unwrap();
    vec.push((re_sk, |m: &str| Some(m.to_string())));

    let re_xox = Regex::new(r"xox[abprso]-(?:[0-9]+-)+[A-Za-z0-9]+").unwrap();
    vec.push((re_xox, |m: &str| Some(m.to_string())));

    let re_hook = Regex::new(r"https://hooks\.slack\.com/services/[A-Z0-9]+/[A-Z0-9]+/[A-Za-z0-9]+").unwrap();
    vec.push((re_hook, |m: &str| Some(m.to_string())));

    let re_google = Regex::new(r"AIza[0-9A-Za-z\-_]{35}").unwrap();
    vec.push((re_google, |m: &str| Some(m.to_string())));

    let re_priv = Regex::new(r"-----BEGIN (?:RSA |DSA |EC |OPENSSH )?PRIVATE KEY-----").unwrap();
    vec.push((re_priv, |m: &str| Some(m.to_string())));
    let re_pgp = Regex::new(r"-----BEGIN PGP PRIVATE KEY BLOCK-----").unwrap();
    vec.push((re_pgp, |m: &str| Some(m.to_string())));

    vec
}

fn is_random(s: &str) -> bool {
    if s.len() < 15 {
        return false;
    }
    if s.chars().all(|c| c == s.chars().next().unwrap()) {
        return false;
    }
    if s.chars().all(|c| c.is_ascii_lowercase()) {
        return false;
    }
    let low = s.to_lowercase();
    if low.contains("password") {
        return false;
    }
    let weak_patterns = ["qwerty", "abcd", "asdf", "zxcv"];
    for pat in weak_patterns {
        if low.contains(pat) && !s.chars().any(|c| c.is_ascii_uppercase()) {
            return false;
        }
    }
    for period in 1..5 {
        if s.len() % period == 0 {
            let sub = &s[0..period];
            if sub.repeat(s.len() / period) == s {
                return false;
            }
        }
        let pat = &s[0..period];
        let repeated = pat.repeat((s.len() / period) + 1);
        if &repeated[0..s.len()] == s {
            return false;
        }
    }
    let entropy = shannon_entropy(s);
    if entropy < 3.0 {
        return false;
    }
    let uniq = s.chars().collect::<HashSet<_>>().len() as f64 / s.len() as f64;
    if s.len() <= 20 {
        if uniq < 0.6 {
            return false;
        }
    } else if s.len() <= 32 {
        if uniq < 0.65 {
            return false;
        }
    } else {
        if uniq < 0.75 {
            return false;
        }
    }
    true
}

fn shannon_entropy(s: &str) -> f64 {
    use std::collections::HashMap;
    let mut freq: HashMap<char, usize> = HashMap::new();
    for c in s.chars() {
        *freq.entry(c).or_insert(0) += 1;
    }
    let len = s.len() as f64;
    let mut entropy = 0.0;
    for &count in freq.values() {
        let p = count as f64 / len;
        entropy -= p * p.log2();
    }
    entropy
}

fn scan_file(
    path: &Path,
    builtin_regexes: &Vec<(Regex, fn(&str) -> Option<String>)>,
    additional_regexes: &Vec<(Regex, bool)>,
    secret_ignores: &HashSet<String>,
    only_matching: bool,
    has_secret: &mut bool,
) -> bool {
    let content = match fs::read_to_string(path) {
        Ok(c) => c,
        Err(_) => match fs::read(path) {
            Ok(bytes) => String::from_utf8_lossy(&bytes).to_string(),
            Err(_) => return false,
        },
    };

    let mut file_has_secret = false;
    let generic_re = Regex::new(r#"(?i)(?:secret|key|token|password)[A-Za-z0-9_]*\s*(?:=>|:=|=|:)\s*['"]?([A-Za-z0-9+/=_\-]{15,})['"]?"#).unwrap();

    for (line_num, line) in content.lines().enumerate() {
        let mut line_has_secret = false;
        let mut matched_tokens: Vec<String> = Vec::new();

        for (re, extractor) in builtin_regexes {
            for mat in re.find_iter(line) {
                let token_raw = mat.as_str();
                let token = extractor(token_raw).unwrap_or(token_raw.to_string());
                if secret_ignores.contains(&token) {
                    continue;
                }
                line_has_secret = true;
                matched_tokens.push(token);
            }
        }

        for (re, has_capture) in additional_regexes {
            for caps in re.captures_iter(line) {
                if *has_capture {
                    if let Some(m) = caps.get(1) {
                        let captured = m.as_str();
                        if !is_random(captured) {
                            continue;
                        }
                        if secret_ignores.contains(captured) {
                            continue;
                        }
                        line_has_secret = true;
                        matched_tokens.push(captured.to_string());
                    }
                } else {
                    if let Some(m) = caps.get(0) {
                        let whole = m.as_str();
                        if secret_ignores.contains(whole) {
                            continue;
                        }
                        line_has_secret = true;
                        matched_tokens.push(whole.to_string());
                    }
                }
            }
        }

        for caps in generic_re.captures_iter(line) {
            if let Some(m) = caps.get(1) {
                let val = m.as_str();
                if !is_random(val) {
                    continue;
                }
                if secret_ignores.contains(val) {
                    continue;
                }
                line_has_secret = true;
                matched_tokens.push(val.to_string());
            }
        }

        if line_has_secret {
            file_has_secret = true;
            *has_secret = true;
            if only_matching {
                for token in matched_tokens {
                    println!("{}:{}:{}", path.display(), line_num + 1, token);
                }
            } else {
                println!("{}:{}:{}", path.display(), line_num + 1, line);
            }
        }
    }

    file_has_secret
}
